class Solution {
public:
    int minAddToMakeValid(string s) {
        int open_count = 0, additions = 0;
        for (char ch : s) {
            if (ch == '(') open_count++;
            else {
                if (open_count > 0) open_count--;
                else additions++;
            }
        }
        return additions + open_count;
    }
};

class Solution {
    public int minAddToMakeValid(String s) {
        int openCount = 0, additions = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '(') openCount++;
            else {
                if (openCount > 0) openCount--;
                else additions++;
            }
        }
        return additions + openCount;
    }
}

var minAddToMakeValid = function(s) {
    let openCount = 0;
    let additions = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '(') {
            openCount++;
        } else {
            if (openCount > 0) openCount--;
            else additions++;
        }
    }
    return additions + openCount;
};
